ON DUPLICATE KEY UPDATE dialogue_id=VALUES(dialogue_id),position_index=VALUES(position_index),speaker_character_id=VALUES(speaker_character_id),speaker_identity_origin=VALUES(speaker_identity_origin),speaker_gender_evidence=VALUES(speaker_gender_evidence),text_target=VALUES(text_target),translation_fa=VALUES(translation_fa),learner_turn=VALUES(learner_turn);
SET @unit := (SELECT id FROM units WHERE unit_key='de-a1-unit-extended-introduction' AND language_level_id=@level LIMIT 1);
SET @lesson := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-integrated-introduction-review' AND language_level_id=@level LIMIT 1);
UPDATE lessons SET unit_id=@unit,title_fa='اول مطمئن شو با چه کسی حرف می‌زنی',activity_selection_rationale='این درس به‌جای مرور شغل و زبان، مهارت تازهٔ شروع گفت‌وگوی رسمی با فرد ناآشنا و جداکردن مبدأ از محل زندگی را اضافه می‌کند.',sequence_rationale='از تشخیص هویت در مکالمه به فهم پاسخ مبدأ/محل زندگی و سپس ساخت پرسش مبدأ حرکت می‌کند.',template_signature='conversation_speaking>multiple_choice>word_order',status='final',audio_status='pending',notes='محتوای قبلی این درس به‌طور کامل با یک هدف آموزشی مستقل و منبع‌دار جایگزین شده است.' WHERE id=@lesson;
ON DUPLICATE KEY UPDATE lesson_id=VALUES(lesson_id),position_index=VALUES(position_index),activity_type=VALUES(activity_type),instruction_fa=VALUES(instruction_fa),selection_reason=VALUES(selection_reason),dialogue_id=VALUES(dialogue_id),payload=VALUES(payload),transformations=VALUES(transformations),audio_text_target=NULL,audio_status='not_required';
ON DUPLICATE KEY UPDATE lesson_id=VALUES(lesson_id),position_index=VALUES(position_index),activity_type=VALUES(activity_type),instruction_fa=VALUES(instruction_fa),selection_reason=VALUES(selection_reason),dialogue_id=VALUES(dialogue_id),payload=VALUES(payload),transformations=VALUES(transformations),audio_text_target=NULL,audio_status='not_required';
