UPDATE lessons SET unit_id=@unit,title_fa='برادرت کجا درس می‌خونه؟ خواهرت کجا زندگی می‌کنه؟',activity_selection_rationale='این درس محور تازهٔ مکان را به واحد خانواده اضافه می‌کند؛ دو درس قبلی بیشتر روی نام، سن و شغل متمرکز بودند.',sequence_rationale='مکالمه دو کاربرد مکان را معرفی می‌کند، تمرین تشخیص فعل‌ها را جدا می‌کند و بازسازی پرسشِ محل زندگی تولید هدایت‌شده می‌دهد.',template_signature='conversation_speaking>multiple_choice>word_order',status='final',audio_status='pending',notes='محتوای قبلی این درس به‌طور کامل با یک هدف آموزشی مستقل و منبع‌دار جایگزین شده است.' WHERE id=@lesson;
