INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-intro-review-conversation',@lesson,1,'conversation_speaking','مکالمه را اجرا کن و اول مطمئن شو طرف مقابل همان کسی است که دنبالش می‌گردی.','مکالمهٔ منبع‌دار برخورد رسمی، نام، مبدأ و محل زندگی را در یک صحنهٔ واقعی کنار هم می‌آورد.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-find-person-formal' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-intro-review-choice',@lesson,2,'multiple_choice','کدام پاسخ هم مبدأ و هم محل زندگی را می‌گوید؟','زبان‌آموز باید بین معرفی نام و پاسخ کامل مبدأ/محل زندگی تمایز بگذارد.',NULL,CAST('{"options":[{"textTarget":"Nein, ich komme aus Deutschland und ich wohne hier in Bern.","translationFa":"نه، من از آلمان می‌آیم و اینجا در برن زندگی می‌کنم.","correct":true},{"textTarget":"Ich heiße Lutz Schmidt.","translationFa":"اسم من لوتس اشمیت است.","correct":false},{"textTarget":"Ja, und Sie? Wie heißen Sie?","translationFa":"بله، و شما؟ اسمتان چیست؟","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-intro-review-order',@lesson,3,'word_order','پرسش «اهل کجا هستید؟» را بساز.','بازسازی پرسش، تفاوت Woher با معرفی صرفِ نام را فعال می‌کند.',NULL,CAST('{"sourceText":"Woher kommen Sie?","sourceTextFa":"اهل کجا هستید؟","tokens":["Woher","kommen","Sie?"],"answer":["Woher","kommen","Sie?"]}' AS JSON),CAST('["sentence_tokenized_for_word_order","persian_translation_added"]' AS JSON),NULL,'not_required')
