INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-family-review-conversation',@lesson,1,'conversation_speaking','دربارهٔ محل تحصیل برادر و محل زندگی خواهر گفت‌وگو کن.','دو جفت پرسش‌وپاسخ منبع‌دار اطلاعات مکانی تازه‌ای به پروفایل خانواده اضافه می‌کنند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-family-study-residence' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
