('act-de-a1-family-review-matching',@lesson,2,'multiple_choice','کدام جمله دربارهٔ محل تحصیل برادر است؟','تمرین تفاوت studieren و wohnen را در همان بافت خانواده می‌سنجد.',NULL,CAST('{"options":[{"textTarget":"Unser Bruder studiert in Berlin.","translationFa":"برادر ما در برلین درس می‌خواند.","correct":true},{"textTarget":"Unsere Schwester wohnt in Hamburg.","translationFa":"خواهر ما در هامبورگ زندگی می‌کند.","correct":false},{"textTarget":"Unser Vater ist LKW-Fahrer.","translationFa":"پدر ما رانندهٔ کامیون است.","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required')
