('act-de-a1-family-review-order',@lesson,3,'word_order','پرسش محل زندگی خواهر را بساز.','پرسش Wo + wohnen برای انتقال مهارت از فهم به تولید هدایت‌شده انتخاب شده است.',NULL,CAST('{"sourceText":"Wo wohnt eure Schwester?","sourceTextFa":"خواهرتان کجا زندگی می‌کند؟","tokens":["Wo","wohnt","eure","Schwester?"],"answer":["Wo","wohnt","eure","Schwester?"]}' AS JSON),CAST('["sentence_tokenized_for_word_order","persian_translation_added"]' AS JSON),NULL,'not_required')
