('act-de-a1-home-review-conversation',@lesson,1,'conversation_speaking','وسایل گم‌شده را بپرس و پاسخ محل آن‌ها را بده.','مکالمهٔ منبع‌دار mein/meine و Ihr/Ihre را در موقعیت پیدا کردن وسایل فعال می‌کند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-find-belongings' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-home-review-order',@lesson,2,'multiple_choice','اگر دربارهٔ چند کتاب صحبت می‌کنیم، کدام پاسخ درست است؟','مفرد و جمع با پاسخ‌های واقعی همان تمرین از هم تفکیک می‌شوند.',NULL,CAST('{"options":[{"textTarget":"Ihre Bücher sind hier.","translationFa":"کتاب‌های شما اینجاست.","correct":true},{"textTarget":"Ihr Heft ist hier.","translationFa":"دفتر شما اینجاست.","correct":false},{"textTarget":"Ihre Tasche ist hier.","translationFa":"کیف شما اینجاست.","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-home-review-matching',@lesson,3,'matching','هر سؤال را به پاسخ درستش وصل کن.','چهار جفت منبع‌دار دامنه را از دفتر و کیف به مداد و کتاب‌ها گسترش می‌دهند.',NULL,CAST('{"pairs":[{"left":"Wo ist mein Heft?","leftFa":"دفترم کجاست؟","right":"Ihr Heft ist hier.","rightFa":"دفتر شما اینجاست."},{"left":"Wo ist mein Bleistift?","leftFa":"مدادم کجاست؟","right":"Ihr Bleistift ist hier.","rightFa":"مداد شما اینجاست."},{"left":"Wo ist meine Tasche?","leftFa":"کیفم کجاست؟","right":"Ihre Tasche ist hier.","rightFa":"کیف شما اینجاست."},{"left":"Wo sind meine Bücher?","leftFa":"کتاب‌هایم کجاست؟","right":"Ihre Bücher sind hier.","rightFa":"کتاب‌های شما اینجاست."}]}' AS JSON),CAST('["source_items_grouped_for_matching","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
