('act-de-a1-shopping-price-review-conversation',@lesson,1,'conversation_speaking','بگو چه چیزی لازم داری و بعد چه چیزی می‌خری.','ثابت نگه‌داشتن کالا باعث می‌شود تفاوت brauchen و kaufen بدون حواس‌پرتی واژگانی دیده شود.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-shopping-needs-buying' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-shopping-price-review-matching',@lesson,2,'matching','هر جمله را به «نیاز» یا «خرید» وصل کن.','نمونه‌های مختلفِ لباس و کالا الگوی فعل را از یک مثال منفرد جدا می‌کنند.',NULL,CAST('{"pairs":[{"left":"Ich brauche eine Tasche.","leftFa":"یک کیف لازم دارم.","right":"نیاز: Tasche","rightFa":"نیاز: کیف"},{"left":"Ich brauche eine Hose.","leftFa":"یک شلوار لازم دارم.","right":"نیاز: Hose","rightFa":"نیاز: شلوار"},{"left":"Ich kaufe eine Tasche.","leftFa":"یک کیف می‌خرم.","right":"خرید: Tasche","rightFa":"خرید: کیف"},{"left":"Ich kaufe ein Paar Schuhe.","leftFa":"یک جفت کفش می‌خرم.","right":"خرید: Schuhe","rightFa":"خرید: کفش"}]}' AS JSON),CAST('["source_items_grouped_for_matching","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-shopping-price-review-order',@lesson,3,'word_order','پرسش «چه چیزی لازم دارید؟» را بساز.','پرسش پایهٔ نیاز برای شروع خرید به بازیابی فعال منتقل می‌شود.',NULL,CAST('{"sourceText":"Was brauchen Sie?","sourceTextFa":"چه چیزی لازم دارید؟","tokens":["Was","brauchen","Sie?"],"answer":["Was","brauchen","Sie?"]}' AS JSON),CAST('["sentence_tokenized_for_word_order","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-shopping-price-total',@level,'مشتری دو بار دربارهٔ قیمت می‌پرسد و پاسخ‌ها عدد یورو و سنت را در قالب واقعی نشان می‌دهند.','app','دو صورت پرسش قیمت و دو پاسخ دقیق یورو/سنت از تمرین‌های قیمت منبع استفاده شده‌اند.')
