('act-de-a1-shopping-checkout-review-conversation',@lesson,1,'conversation_speaking','دو روش پرسیدن قیمت و پاسخ یورو/سنت را اجرا کن.','جمله‌های منبع‌دار مهارت خواندن قیمت دقیق را مستقل از مقدار کالا تمرین می‌دهند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-shopping-price-total' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
