('act-de-a1-shopping-checkout-review-response',@lesson,2,'multiple_choice','کدام پرسش دربارهٔ جمع کل خرید است؟','تفاوت kostet با macht در کاربرد فروشگاهی به‌صورت معنایی سنجیده می‌شود.',NULL,CAST('{"options":[{"textTarget":"Wie viel macht das bitte?","translationFa":"جمعش لطفاً چقدر می‌شود؟","correct":true},{"textTarget":"Wie viel kostet das?","translationFa":"این چقدر قیمت دارد؟","correct":false},{"textTarget":"Was kostet das?","translationFa":"قیمت این چقدر است؟","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-shopping-checkout-review-order',@lesson,3,'fill_blank','جمع کل را با عدد درست کامل کن.','تمرین عدد دقیق یورو و سنت، فهم شنیداری/خواندنی قیمت را به بازیابی هدایت‌شده وصل می‌کند.',NULL,CAST('{"sourceText":"Das macht 63 Euro und 10 Cent.","sourceTextFa":"جمعش ۶۳ یورو و ۱۰ سنت می‌شود.","blankedText":"Das macht ___.","blankedTextFa":"جمعش ___ می‌شود.","choices":["63 Euro und 10 Cent","35 Euro und 15 Cent","70 Euro und 92 Cent"],"choicesFa":["۶۳ یورو و ۱۰ سنت","۳۵ یورو و ۱۵ سنت","۷۰ یورو و ۹۲ سنت"],"answer":"63 Euro und 10 Cent"}' AS JSON),CAST('["source_sentence_blank_created","persian_translation_added"]' AS JSON),NULL,'not_required')
