INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-food-preference-review-conversation',@lesson,1,'conversation_speaking','قهوه سفارش بده و دقیق بگو چه چیزی داخلش می‌خواهی.','چهار نوبت منبع‌دار سفارش و شخصی‌سازی نوشیدنی را به‌صورت پیوسته تمرین می‌کنند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-coffee-customization' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-food-preference-review-choice',@lesson,2,'choose_response','برای «Mit Milch und Zucker?» پاسخ درست را انتخاب کن.','پاسخ فقط با شکر مستقیماً مهارت تعیین ترجیح در سفارش را می‌سنجد.',NULL,CAST('{"promptTarget":"Mit Milch und Zucker?","promptFa":"با شیر و شکر؟","options":[{"textTarget":"Bitte nur mit Zucker.","translationFa":"لطفاً فقط با شکر.","correct":true},{"textTarget":"Bitte eine Tasse Kaffee.","translationFa":"لطفاً یک فنجان قهوه.","correct":false},{"textTarget":"Gibt es auch Kuchen?","translationFa":"کیک هم دارید؟","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-food-preference-review-order',@lesson,3,'word_order','بعد از نوشیدنی بپرس آیا کیک هم هست.','این پرسش سفارش را از یک قلم به بررسی قلم دوم گسترش می‌دهد.',NULL,CAST('{"sourceText":"Gibt es auch Kuchen?","sourceTextFa":"کیک هم هست؟","tokens":["Gibt","es","auch","Kuchen?"],"answer":["Gibt","es","auch","Kuchen?"]}' AS JSON),CAST('["sentence_tokenized_for_word_order","persian_translation_added"]' AS JSON),NULL,'not_required')
